INSERT INTO "Preguntas" ("idPregunta", "pregunta", "respuestaA", "respuestaB", "respuestaC", "respuestaD", "respuesta", "test", "tema", "temaTest", "imagen", "pregunta2", "audio", "explicacion", "imagenExplicacion", "configuracionPregunta", "pregunta_acertada") VALUES (884, 'Esta mañana la Luna se ha escondido <br> detrás de una rama, debajo de un olivo. <br> La Luna se va a la cama, <br> queda entre las hojas y el trigo, <br> en la charca croan las ranas <br> haciendo mucho ruido.<br>Cantan los pajarillos <br> asomando sus cabezas <br> en lo alto de sus nidos.<br>Duerme la Luna, canta la chicharra y saltan los grillos, <br> tú escuchas mis versos <br> mientras yo los escribo.<br>Los niños juegan a escuchar <br> de la Luna los ronquidos. <br> <br> Juan Biró. La Luna.', 'Por la mañana', 'Por la noche', 'Por la tarde', '', 'a', 29, 5021, 1, 'imagen_max_tamano_comprension_lectora_la_luna', '¿Cuándo se acuesta la luna?', '', '', '', 'ØÚÉÆáÄæÊÚé³ØÖÂÕ¢ÝÓÓÝÃ', 0);
