INSERT INTO "Preguntas" ("idPregunta", "pregunta", "respuestaA", "respuestaB", "respuestaC", "respuestaD", "respuesta", "test", "tema", "temaTest", "imagen", "pregunta2", "audio", "explicacion", "imagenExplicacion", "configuracionPregunta", "pregunta_acertada") VALUES (892, 'Estaban una vez discutiendo el Sol y el viento sobre cuál de los dos era el más fuerte, cuando de pronto vieron que por un camino venía un hombre que llevaba puesto un abrigo. El viento le dijo al Sol:<br> - Mira aquel hombre que lleva un abrigo. El que consiga que se lo quite será el más fuerte.<br>Y dicho esto, mientras el Sol se ocultaba entre las nubes, el viento empezó a soplar y soplar muy fuerte, pero cuanto más soplaba, más fuerte se sujetaba el abrigo el hombre. Al cabo de un rato el viento se cansó de tanto soplar sin conseguir nada.<br> Entonces el Sol salió y empezó a calentar más y más, tanto que el hombre comenzó a sudar, y tanto calor sentía que al final se quitó el abrigo.<br> El Sol había conseguido con sus rayos lo que el viento con toda su fuerza no pudo.<br>', 'El Sol', 'El viento', 'Los dos serán igual de fuerte', '', 'a', 37, 10021, 1, 'imagen_max_tamano_comprension_lectora_el_sol_y_el_viento', '¿Quién consiguió al final ser "el más fuerte"?', '', '', '', 'ØÚÉÆáÄæÊÚé³ØÖÂÕ¢ÝÓÓÝÃ', 0);
