INSERT INTO "Preguntas" ("idPregunta", "pregunta", "respuestaA", "respuestaB", "respuestaC", "respuestaD", "respuesta", "test", "tema", "temaTest", "imagen", "pregunta2", "audio", "explicacion", "imagenExplicacion", "configuracionPregunta", "pregunta_acertada") VALUES (898, 'Estaban una vez discutiendo el Sol y el viento sobre cuál de los dos era el más fuerte, cuando de pronto vieron que por un camino venía un hombre que llevaba puesto un abrigo. El viento le dijo al Sol:<br> - Mira aquel hombre que lleva un abrigo. El que consiga que se lo quite será el más fuerte.<br>Y dicho esto, mientras el Sol se ocultaba entre las nubes, el viento empezó a soplar y soplar muy fuerte, pero cuanto más soplaba, más fuerte se sujetaba el abrigo el hombre. Al cabo de un rato el viento se cansó de tanto soplar sin conseguir nada.<br> Entonces el Sol salió y empezó a calentar más y más, tanto que el hombre comenzó a sudar, y tanto calor sentía que al final se quitó el abrigo.<br> El Sol había conseguido con sus rayos lo que el viento con toda su fuerza no pudo.<br>', 'Que empezó a sudar', 'Que se resfrió', 'Que se perdió por el camino', '', 'a', 43, 10021, 1, 'imagen_max_tamano_comprension_lectora_el_sol_y_el_viento', '¿Qué le pasó al hombre cuando el Sol empezó a calentar más?', '', '', '', 'ØÚÉÆáÄæÊÚé³ØÖÂÕ¢ÝÓÓÝÃ', 0);
INSERT INTO "Preguntas" ("idPregunta", "pregunta", "respuestaA", "respuestaB", "respuestaC", "respuestaD", "respuesta", "test", "tema", "temaTest", "imagen", "pregunta2", "audio", "explicacion", "imagenExplicacion", "configuracionPregunta", "pregunta_acertada") VALUES (899, 'Estaban una vez discutiendo el Sol y el viento sobre cuál de los dos era el más fuerte, cuando de pronto vieron que por un camino venía un hombre que llevaba puesto un abrigo. El viento le dijo al Sol:<br> - Mira aquel hombre que lleva un abrigo. El que consiga que se lo quite será el más fuerte.<br>Y dicho esto, mientras el Sol se ocultaba entre las nubes, el viento empezó a soplar y soplar muy fuerte, pero cuanto más soplaba, más fuerte se sujetaba el abrigo el hombre. Al cabo de un rato el viento se cansó de tanto soplar sin conseguir nada.<br> Entonces el Sol salió y empezó a calentar más y más, tanto que el hombre comenzó a sudar, y tanto calor sentía que al final se quitó el abrigo.<br> El Sol había conseguido con sus rayos lo que el viento con toda su fuerza no pudo.<br>', 'El hombre se sujetaba cada vez más el abrigo', 'El hombre se puso a tomar el sol', 'El Sol se metió tras una nube', '', 'a', 44, 10021, 1, 'imagen_max_tamano_comprension_lectora_el_sol_y_el_viento', 'El viento se cansó de soplar porque:', '', '', '', 'ØÚÉÆáÄæÊÚé³ØÖÂÕ¢ÝÓÓÝÃ', 0);
INSERT INTO "Preguntas" ("idPregunta", "pregunta", "respuestaA", "respuestaB", "respuestaC", "respuestaD", "respuesta", "test", "tema", "temaTest", "imagen", "pregunta2", "audio", "explicacion", "imagenExplicacion", "configuracionPregunta", "pregunta_acertada") VALUES (900, 'Saturno es el segundo planeta más grande del Sistema Solar y sus anillos son visibles desde la Tierra. Es el único planeta que tiene una densidad menor que la del agua, es decir, que si lo colocásemos encima de un inmenso océano, Saturno flotaría como un gigantesco balón de playa.<br>El día en Saturno dura 10 horas y tarda 29 años en orbitar alrededor del Sol.<br>La temperatura media en Saturno es de 125 grados bajo cero y los principales componentes de la atmósfera son hidrógeno, helio y sulfuros.<br>Saturno tiene tres anillos principales: dos de ellos son muy brillantes y el tercero es más tenue. No se sabe de qué están compuestos exactamente, pero los científicos piensan que están formados por hielo mezclado con polvo y piedras.<br>Saturno, además, es el planeta con más satélites. Mientras que la Tierra solo tiene uno, la Luna, Saturno tiene dieciocho.<br>El mayor de ellos se llama Titán.', 'Un planeta', 'Un satélite', 'Una estrella', '', 'a', 45, 15021, 1, 'imagen_max_tamano_comprension_lectora_saturno', '¿Qué es saturno?', '', '', '', 'ØÚÉÆáÄæÊÚé³ØÖÂÕ¢ÝÓÓÝÃ', 0);
