INSERT INTO "Preguntas" ("idPregunta", "pregunta", "respuestaA", "respuestaB", "respuestaC", "respuestaD", "respuesta", "test", "tema", "temaTest", "imagen", "pregunta2", "audio", "explicacion", "imagenExplicacion", "configuracionPregunta", "pregunta_acertada") VALUES (908, 'Según los últimos datos de la comunidad científica, los polos de la Tierra se están derritiendo a pasos agigantados. Los grandes icebergs pueden comenzar en poco tiempo a invadir los mares y océanos de nuestro planeta ocasionando grandes daños a los navegantes y generando peligros en las costas a las que se puedan acercar.<br>Parece que el ser humano no acaba de tomar conciencia de los graves daños que se están ocasionando por la contaminación excesiva que se genera cada día.<br>A esto hay que añadir las consecuencias de la deforestación de las selvas y espacios naturales que siempre mantuvieron un equilibrio en nuestro planeta. Todos debemos poner nuestros recursos para evitar que esto siga ocurriendo.<br>La subida del nivel de los mares y océanos durante los años venideros puede llegar a inundar la mayoría de las playas de la Tierra, con las consecuencias que esto supondría.', 'Cada vez hay menos árboles en la Tierra', 'El nivel de los mares está descendiendo', 'Los polos de la Tierra están aumentando', '', 'a', 53, 20021, 1, 'imagen_max_tamano_comprension_lectora_cambio_climatico', '¿Cuál es uno de los problemas originados por el cambio climático?', '', '', '', 'ØÚÉÆáÄæÊÚé³ØÖÂÕ¢ÝÓÓÝÃ', 0);
