INSERT INTO "Preguntas" ("idPregunta", "pregunta", "respuestaA", "respuestaB", "respuestaC", "respuestaD", "respuesta", "test", "tema", "temaTest", "imagen", "pregunta2", "audio", "explicacion", "imagenExplicacion", "configuracionPregunta", "pregunta_acertada") VALUES (916, 'Érase una vez una semilla que cayó entre las rocas y no podía salir.<br>Se puso muy triste y dijo:<br>- Nunca llegaré a ser una planta, sin tierra, sin agua y sin sol.<br>Un pájaro oyó a la semilla y fue a ver a la madre tierra.<br>- La semilla está atrapada entre las rocas y no puede salir.<br>Entonces, la madre tierra llamó al sol y a la lluvia. Los tres juntos fueron donde la semilla y le dijeron: Abre tus hojitas al viento y al sol, nacerá de tu tallo una bella flor.<br>La lluvia comenzó a caer. La semilla se hundió en la tierra fértil. Tomó la fuerza con el agua y el sol y empezó a germinar.<br>Las hojas parecían dos ojitos verdes maravillados del mundo. El tallo siguió creciendo y creciendo... De pronto nació un capullo y luego brotó la flor: un cículo con pecas rodeado de pétalos amarillos.<br>¡ Aquella flor tan hermosa era un girasol!<br><br>(Isabel Freire de Matos)', 'Entre las rocas', 'En el camino', 'En el mar', '', 'a', 61, 25021, 1, 'imagen_max_tamano_comprension_lectora_la_semilla', '¿Dónde cayó la semilla?', '', '', '', 'ØÚÉÆáÄæÊÚé³ØÖÂÕ¢ÝÓÓÝÃ', 0);
