INSERT INTO "Preguntas" ("idPregunta", "pregunta", "respuestaA", "respuestaB", "respuestaC", "respuestaD", "respuesta", "test", "tema", "temaTest", "imagen", "pregunta2", "audio", "explicacion", "imagenExplicacion", "configuracionPregunta", "pregunta_acertada") VALUES (923, 'Érase una vez una semilla que cayó entre las rocas y no podía salir.<br>Se puso muy triste y dijo:<br>- Nunca llegaré a ser una planta, sin tierra, sin agua y sin sol.<br>Un pájaro oyó a la semilla y fue a ver a la madre tierra.<br>- La semilla está atrapada entre las rocas y no puede salir.<br>Entonces, la madre tierra llamó al sol y a la lluvia. Los tres juntos fueron donde la semilla y le dijeron: Abre tus hojitas al viento y al sol, nacerá de tu tallo una bella flor.<br>La lluvia comenzó a caer. La semilla se hundió en la tierra fértil. Tomó la fuerza con el agua y el sol y empezó a germinar.<br>Las hojas parecían dos ojitos verdes maravillados del mundo. El tallo siguió creciendo y creciendo... De pronto nació un capullo y luego brotó la flor: un cículo con pecas rodeado de pétalos amarillos.<br>¡ Aquella flor tan hermosa era un girasol!<br><br>(Isabel Freire de Matos)', 'Un capullo', 'La semilla', 'El tallo', '', 'a', 68, 25021, 1, 'imagen_max_tamano_comprension_lectora_la_semilla', '¿Qué nació antes de brotar la flor?', '', '', '', 'ØÚÉÆáÄæÊÚé³ØÖÂÕ¢ÝÓÓÝÃ', 0);
INSERT INTO "Preguntas" ("idPregunta", "pregunta", "respuestaA", "respuestaB", "respuestaC", "respuestaD", "respuesta", "test", "tema", "temaTest", "imagen", "pregunta2", "audio", "explicacion", "imagenExplicacion", "configuracionPregunta", "pregunta_acertada") VALUES (924, 'Era una gran árbol lleno de hojas hasta un día en que apareció el viento que comenzó a soplar y soplar.<br>Las hojas iban cayendo al suelo unas tras otras. Unas se llenaban de barro, otras las pisaban los niños y otras las recogía el barrendero.<br>Había en lo alto de una ramita dos hojas que lloraban porque no querían caer al suelo. No querían llenarse de barro y que los niños las pisaran.<br>Cada vez que venía el viento se movían pero se agarraban con su rabito muy fuerte a la rama del árbol.<br>De pronto dijo la más pequeña "tengo una idea, mira aquel pájaro que vuela por el cielo, por qué no esperamos que venga un gran viento y volamos como él".<br>A la otra hoja le pareció una estupenda idea.<br>Cuando sopló un viento muy fuerte las dos hojitas soltaron su rabito de la rama del árbol y volaron por el aire, muy alto muy alto hasta desaparecer junto a los pájaros del cielo.', 'Dos', 'Una', 'Cinco', '', 'a', 69, 30021, 1, 'imagen_max_tamano_comprension_lectora_las_dos_hojas', '¿Cuántas hojas eran las que no querían caer al suelo?', '', '', '', 'ØÚÉÆáÄæÊÚé³ØÖÂÕ¢ÝÓÓÝÃ', 0);
