INSERT INTO "Preguntas" ("idPregunta", "pregunta", "respuestaA", "respuestaB", "respuestaC", "respuestaD", "respuesta", "test", "tema", "temaTest", "imagen", "pregunta2", "audio", "explicacion", "imagenExplicacion", "configuracionPregunta", "pregunta_acertada") VALUES (927, 'Era una gran árbol lleno de hojas hasta un día en que apareció el viento que comenzó a soplar y soplar.<br>Las hojas iban cayendo al suelo unas tras otras. Unas se llenaban de barro, otras las pisaban los niños y otras las recogía el barrendero.<br>Había en lo alto de una ramita dos hojas que lloraban porque no querían caer al suelo. No querían llenarse de barro y que los niños las pisaran.<br>Cada vez que venía el viento se movían pero se agarraban con su rabito muy fuerte a la rama del árbol.<br>De pronto dijo la más pequeña "tengo una idea, mira aquel pájaro que vuela por el cielo, por qué no esperamos que venga un gran viento y volamos como él".<br>A la otra hoja le pareció una estupenda idea.<br>Cuando sopló un viento muy fuerte las dos hojitas soltaron su rabito de la rama del árbol y volaron por el aire, muy alto muy alto hasta desaparecer junto a los pájaros del cielo.', 'Por el rabito', 'Con los brazos', 'Por el tallo', '', 'a', 72, 30021, 1, 'imagen_max_tamano_comprension_lectora_las_dos_hojas', '¿Cómo se agarraban las hojas a la rama cuando venía el viento?', '', '', '', 'ØÚÉÆáÄæÊÚé³ØÖÂÕ¢ÝÓÓÝÃ', 0);
