INSERT INTO "Preguntas" ("idPregunta", "pregunta", "respuestaA", "respuestaB", "respuestaC", "respuestaD", "respuesta", "test", "tema", "temaTest", "imagen", "pregunta2", "audio", "explicacion", "imagenExplicacion", "configuracionPregunta", "pregunta_acertada") VALUES (932, 'Unos ratoncitos, jugando en un prado, despertaron a un león que dormía tranquilamente al pie de un árbol. La fiera, levantándose de pronto, atrapó entre sus garras al más atrevido de la pandilla.<br>El ratoncillo, lleno de miedo, prometió al león que si le perdonaba la vida estaría a su servicio; y aunque esta promesa lo hizo reír, el león terminó por soltarlo.<br>Tiempo después, el león cayó en las redes que un cazador le había tendido y como, a pesar de su fuerza, no podía librarse, rugió y rugió, hasta que su voz fue escuchada por toda la selva.<br>El ratoncito, al oírlo, acudió presuroso y rompió las redes con sus afilados dientes. De esta manera el pequeño ratoncito cumplió su promesa, y salvó la vida del león.<br>El león meditó seriamente en el favor que acababa de recibir y prometió en adelante ser más generoso.<br>', 'En un prado', 'En la selva', 'En una casa', '', 'a', 77, 35021, 1, 'imagen_max_tamano_comprension_lectora_el_leon_y_el_raton', '¿Dónde estaban jugando los ratoncitos?', '', '', '', 'ØÚÉÆáÄæÊÚé³ØÖÂÕ¢ÝÓÓÝÃ', 0);
