INSERT INTO "Preguntas" ("idPregunta", "pregunta", "respuestaA", "respuestaB", "respuestaC", "respuestaD", "respuesta", "test", "tema", "temaTest", "imagen", "pregunta2", "audio", "explicacion", "imagenExplicacion", "configuracionPregunta", "pregunta_acertada") VALUES (938, 'Las mariposas son animales invertebrados y pertenecen al grupo de los insectos, las mariposas tienen dos pares de alas cubiertas de unas diminutas escamas que dan color a las alas. La mayor parte viven un mes o un mes y medio, algunas viven solamente de día y otras de noche y se denominan polillas.<br>Las hembras ponen los huevos cuidadosamente en una planta, pasado diez días nacen las orugas o larvas, que se alimentan de: hojas, raíces, frutos, flores y semillas. Luego se transforman en crisálidas, es decir, se encierran en una especie de bolsa y, adquieren forma de mariposa.<br>La mariposa cambia su forma de alimentarse, por medio de una especie de trompa, succionando el néctar de las flores.', 'Invertebrados', 'Vertebrados', '', '', 'a', 83, 40021, 1, 'imagen_max_tamano_comprension_lectora_las_mariposas', '¿Qué tipo de animales son las mariposas?', '', '', '', 'ØÚÉÆáÄæÊÚé³ØÖÂÕ¢ÝÓÓÝÃ', 0);
