INSERT INTO "Preguntas" ("idPregunta", "pregunta", "respuestaA", "respuestaB", "respuestaC", "respuestaD", "respuesta", "test", "tema", "temaTest", "imagen", "pregunta2", "audio", "explicacion", "imagenExplicacion", "configuracionPregunta", "pregunta_acertada") VALUES (946, 'Hoy es el cumpleaños de Ernesto, que lo celebra en casa de su abuela Erminia.<br>Ernesto está muy contento porque se ha reunido toda su familia: Además de su abuela, está su madre que se llama igual que su abuela, su padre, que se llama igual que él, su hermano pequeño Enrique que tiene cuatro años y su hermano mayor cuyo nombre también empieza por E y que tiene seis años más que Enrique.<br>También han venido sus diez primos de Barcelona, tres de Madrid y cinco de Canarias.<br>Para la celebración han comprado una tarta de fresas y queso con siete velas, magdalenas y bizcochos.<br>Para beber tienen leche, zumos y batidos de una fruta de color roja.<br>Ernesto se ha llevado todo el día jugando, ha sido el día más feliz de su vida.', '7 años', '10 años', '4 años', '', 'a', 91, 46021, 1, 'imagen_max_tamano_comprension_lectora_cumple_ernesto', '¿Cuántos años cumple Ernesto?', '', 'Son 7 años porque la tarta tiene 7 velas.', '', 'ØÚÉÆáÄæÊÚé³ØÖÂÕ¢ÝÓÓÝÃ', 0);
